/**
 * @method
 * @name scwin.check_corp_reg_no
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm
 * @returns
 * @hidden N
*/
scwin.check_corp_reg_no = async function (fm) {
    /* sdd-asis-lifecycle:begin check_corp_reg_no — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const no = $c.util.getComponent("dma_checkFormReq").get("corpRegNo");
    let chk_digit;
    let corp_reg_no;
    let sum;
    let chk;
    if (no.length != 13) {
        await $c.win.alert("법인등록번호를 확인하여 주십시오" + "\n" + "법인등록번호 Length Error");
        return false;
    }
    chk_digit = no.substring(12, 13);
    corp_reg_no = no.substring(0, 12);
    sum = 0;
    sum += corp_reg_no.substring(0, 1) * 1;
    sum += corp_reg_no.substring(1, 2) * 2;
    sum += corp_reg_no.substring(2, 3) * 1;
    sum += corp_reg_no.substring(3, 4) * 2;
    sum += corp_reg_no.substring(4, 5) * 1;
    sum += corp_reg_no.substring(5, 6) * 2;
    sum += corp_reg_no.substring(6, 7) * 1;
    sum += corp_reg_no.substring(7, 8) * 2;
    sum += corp_reg_no.substring(8, 9) * 1;
    sum += corp_reg_no.substring(9, 10) * 2;
    sum += corp_reg_no.substring(10, 11) * 1;
    sum += corp_reg_no.substring(11, 12) * 2;
    chk = 0;
    chk = (10 - (sum % 10)) % 10;
    if (chk_digit !== chk) {
        await $c.win.alert("법인등록번호에 오류가 있습니다.");
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


