    /* sdd-asis-lifecycle:begin fn_getCorpRegNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sCorpRegNo = $c.util.getComponent('ipt_corpRegNo1').getValue() + $c.util.getComponent('ipt_corpRegNo2').getValue();
    const sCorpRegNoOrg = $c.util.getComponent('ipt_corpRegNoOrignal').getValue();
    let sRtn = "";
    if (sCorpRegNo.length == 13 && sCorpRegNo.indexOf("*") > -1 && sCorpRegNoOrg.length == 13) {
        for (let i = 0; i < sCorpRegNoOrg.length; i++) {
