            const cCharAt = sBzRegNo.charAt(i);
            if (cCharAt === '*') {
                sRtn += sBzRegNoOrg.charAt(i);
            } else {
                sRtn += cCharAt;
            }
        }
    } else {
        sRtn = sBzRegNo;
    }
    return sRtn;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.check_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.check_form = async function () {
    /* sdd-asis-lifecycle:begin check_form — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.JLDINF05400 || { elements: [] });
    if ($c.util.getComponent('ipt_cntrCd').getValue()=== '410') {
        $c.util.getComponent("dma_checkFormReq").set("corpRegNoP", $c.util.getComponent('ipt_corpRegNo1').getValue()+ '-' + $c.util.getComponent('ipt_corpRegNo2').getValue());
        $c.util.getComponent("dma_checkFormReq").set("bzRegNoP", $c.util.getComponent('ipt_bzRegNo1').getValue()+ '-' + $c.util.getComponent('ipt_bzRegNo2').getValue()+ '-' + $c.util.getComponent('ipt_bzRegNo3').getValue());
        $c.util.getComponent("ipt_telNo").setValue($c.util.getComponent('ipt_telNo1').getValue()+ "-" + $c.util.getComponent('ipt_telNo2').getValue()+ "-" + $c.util.getComponent('ipt_telNo3').getValue());
    }
    if (!await scwin.dataValidation()) {
        return;
    }
    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
        return;
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return;
    }
    let tmp = '';
    const cnt = parseInt($c.util.getComponent('ipt_acntclsCnt').getValue(), 10);
    for (let i = 1; i < cnt + 1; i++) {
        if (i == 1) {
            tmp = tmp + $('#acntcls_mm' + i).val();
        } else {
            tmp = tmp + ', ' + $('#acntcls_mm' + i).val();
        }
    }
    $c.util.getComponent('ipt_acntclsTmp').setValue(tmp);
    if (await $c.win.confirm("신청하시겠습니까?")) {
        const width = 800;
        const height = 700;
        const left = (screen.width - width) / 3;
        const top = (screen.height - height) / 3;
        let _popupWindow;
        _popupWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/common/corpUpd.do?method=corpUpdReqCheck", unresolved: "nav:" + "/common/corpUpd.do?method=corpUpdReqCheck" }; })();
        fm.action = '/common/corpUpd.do?method=corpUpdReqCheck';

    }
    /* sdd-asis-lifecycle:end */
};


